// 纯工具函数：可在 Node 中测试，不触碰 DOM（顶层声明，浏览器与 Node 均可见）
function esc(s){
  return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});
}
function formatBytes(n){
  n=Number(n)||0;
  if(n<=0) return "0 B";
  var u=["B","KB","MB","GB"]; var i=0;
  while(n>=1024&&i<u.length-1){n/=1024;i++;}
  return (n>=100||i===0?Math.round(n):n.toFixed(1))+" "+u[i];
}
// 标准字形集合：大写 / 小写 / 数字 / 标点
function buildGlyphSet(){
  var s="";
  for(var i=65;i<=90;i++) s+=String.fromCharCode(i);
  for(var j=97;j<=122;j++) s+=String.fromCharCode(j);
  for(var k=48;k<=57;k++) s+=String.fromCharCode(k);
  s+="!@#$%^&*()_+-={}[]:;\"'<>,.?/|\\~";
  return s.split("");
}
// 生成可移植的样张 SVG（fontB64 为 base64 字体数据，可嵌入使其独立可用）
function buildSpecimenSVG(o){
  o=o||{};
  var name=o.name||"Font";
  var text=o.text||"The quick brown fox jumps over the lazy dog";
  var glyphs=o.glyphs||[];
  var opts=o.opts||{};
  var size=opts.size||64;
  var color=opts.color||"#FFFFFF";
  var bg=opts.bg||"#0A0A0B";
  var align=opts.align||"left";
  var weight=opts.weight||400;
  var fontB64=o.fontB64||null;
  var family="SpecFont";
  var face=fontB64?('@font-face{font-family:"'+family+'";src:url(data:font/woff2;base64,'+fontB64+') format("woff2");font-display:block;font-weight:100 900;}'):'';
  var w=1200,h=760;
  var perRow=12, cellW=(w-80)/perRow, cellH=cellW;
  var grid="";
  glyphs.slice(0,84).forEach(function(ch,idx){
    var col=idx%perRow, row=Math.floor(idx/perRow);
    var x=40+col*cellW, y=380+row*cellH;
    grid+='<rect x="'+x+'" y="'+y+'" width="'+(cellW-4)+'" height="'+(cellH-4)+'" fill="none" stroke="rgba(255,255,255,0.08)"/>';
    grid+='<text x="'+(x+cellW/2)+'" y="'+(y+cellH/2+size*0.28)+'" font-size="'+Math.min(size*0.62,cellH*0.55)+'" fill="'+color+'" text-anchor="middle" font-family="'+family+',sans-serif">'+esc(ch)+'</text>';
  });
  var anchor=align==="center"?"middle":(align==="right"?"end":"start");
  var tx=align==="center"?w/2:(align==="right"?w-40:40);
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'">'
    +'<defs>'+face+'</defs>'
    +'<rect width="'+w+'" height="'+h+'" fill="'+bg+'"/>'
    +'<text x="40" y="74" font-size="34" font-weight="700" fill="'+color+'" font-family="'+family+',sans-serif">'+esc(name)+'</text>'
    +'<text x="40" y="104" font-size="13" fill="rgba(255,255,255,0.5)" font-family="sans-serif">TYPE SPECIMEN · generated by FontForge</text>'
    +'<text x="'+tx+'" y="190" font-size="'+size+'" font-weight="'+weight+'" fill="'+color+'" text-anchor="'+anchor+'" font-family="'+family+',sans-serif">'+esc(text)+'</text>'
    +'<text x="40" y="350" font-size="15" fill="rgba(255,255,255,0.5)" font-family="sans-serif" letter-spacing="2">GLYPH SET</text>'
    +grid
    +'</svg>';
  return svg;
}
if(typeof module!=='undefined'&&module.exports){
  module.exports={esc:esc,formatBytes:formatBytes,buildGlyphSet:buildGlyphSet,buildSpecimenSVG:buildSpecimenSVG};
}
if(typeof window!=='undefined'){
  window.FontForgePure={esc:esc,formatBytes:formatBytes,buildGlyphSet:buildGlyphSet,buildSpecimenSVG:buildSpecimenSVG};
}
